        :duplicated_when_clause => ["'when' clause on line %d duplicates 'when' clause on line %d and is ignored", :verbose],
        :float_out_of_range => ["Float %.*s%s out of range", :verbose],
        :ignored_frozen_string_literal => ["'frozen_string_literal' is ignored after any tokens", :verbose],
        :indentation_mismatch => ["mismatched indentations at '%.*s' with '%.*s' at %d", :verbose],
        :integer_in_flip_flop => ["integer literal in flip-flop", :default],
        :invalid_character => ["invalid character syntax; use %s%s%s", :default],
        :invalid_magic_comment_value => ["invalid value for %.*s: %.*s", :verbose],
        :invalid_numbered_reference => ["'%.*s' is too big for a number variable, always nil", :default],
        :keyword_eol => ["`%.*s` at the end of line without an expression", :verbose],
        :literal_in_condition_default => ["%sliteral in %s", :default],
        :literal_in_condition_verbose => ["%sliteral in %s", :verbose],
        :shareable_constant_value_line => ["'shareable_constant_value' is ignored unless in comment-only line", :verbose],
        :shebang_carriage_return => ["shebang line ending with \\r may cause problems", :default],
        :unexpected_carriage_return => ["encountered \\r in middle of line, treated as a mere space", :default],
        :unreachable_statement => ["statement not reached", :verbose],
        :unused_local_variable => ["assigned but unused variable - %.*s", :verbose],
        :void_statement => ["possibly useless use of %.*s in void context", :verbose],
